// Кейс .qa/tests/admin-plans/AP-09. ПИШЕТ данные на проде: только аккаунт «בדיקה», отмена назначения в finally. Не @prod-safe.
import { test, expect } from '@playwright/test';
import { setLanguage, openPlansTab, targetRow, dialogFields, choosePlan, revokeIfAssigned, isoDate, enDate } from './plans-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Plans', () => {
  test('Assign, change/extend and revoke a plan for «בדיקה», reason required #ca557707 @desktop @writes', async ({ page }) => {
    test.setTimeout(180_000);
    await setLanguage(page, 'en');

    // Старт только с «чистого» состояния: если осталось назначение от прошлого прогона — снять.
    await revokeIfAssigned(page, 'QA-AUTO pre-clean #ca557707');

    try {
      // 1. Assign: без причины Save неактивна
      let row = await targetRow(page);
      await row.getByRole('button', { name: 'Assign plan', exact: true }).click();
      let f = dialogFields(page);
      await expect(f.dialog).toBeVisible();
      await choosePlan(page, f.plan, 'Pro Tech');
      await f.until.fill(isoDate(30));
      await f.reason.fill('');
      await expect(f.save).toBeDisabled(); // источник: #2ae9da4d — причина обязательна

      // 2. С причиной — сохранение
      await f.reason.fill('QA-AUTO assign #ca557707');
      await expect(f.save).toBeEnabled();
      await f.save.click();
      await expect(f.dialog).toBeHidden();
      await expect(page.getByText('Plan updated')).toBeVisible();

      row = await targetRow(page);
      await expect(row).toContainText('Pro Tech');
      await expect(row).toContainText('Assigned');
      await expect(row).toContainText(enDate(30));
      await expect(row.getByRole('button', { name: 'Change / extend', exact: true })).toBeVisible();
      await expect(row.getByRole('button', { name: 'Revoke', exact: true })).toBeVisible();

      // 3. Change / extend — новая дата
      await row.getByRole('button', { name: 'Change / extend', exact: true }).click();
      f = dialogFields(page);
      await f.until.fill(isoDate(35));
      await f.reason.fill('QA-AUTO extend #ca557707');
      await f.save.click();
      await expect(f.dialog).toBeHidden();
      row = await targetRow(page);
      await expect(row).toContainText(enDate(35));

      // 4. Revoke: без причины кнопка неактивна, с причиной — возврат к своему тарифу
      await row.getByRole('button', { name: 'Revoke', exact: true }).click();
      f = dialogFields(page);
      await f.reason.fill('');
      await expect(f.revoke).toBeDisabled();
      await f.reason.fill('QA-AUTO revoke #ca557707');
      await f.revoke.click();
      await expect(f.dialog).toBeHidden();
      row = await targetRow(page);
      await expect(row.getByRole('button', { name: 'Assign plan', exact: true })).toBeVisible();
      await expect(row).not.toContainText('Assigned');
    } finally {
      // Очистка всегда, даже при падении проверки.
      await revokeIfAssigned(page, 'QA-AUTO cleanup #ca557707');
    }
  });
});
